DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.hc_action(uuid,uuid,uuid,text,jsonb)'::regprocedure) INTO definition; definition := replace(definition, 'UPDATE public.hc_transfers SET state=''ready'' WHERE id=tr.id;', 'IF encode(sha256(coalesce((SELECT string_agg(bytes, ''''::bytea ORDER BY position) FROM public.hc_chunks WHERE transfer_id=tr.id),''''::bytea)),''hex'') <> tr.sha256 THEN RAISE EXCEPTION ''File integrity mismatch''; END IF; UPDATE public.hc_transfers SET state=''ready'' WHERE id=tr.id;'); EXECUTE definition; END $$;